"""
Exhaustive census: the order-pq theorem and the criterion that fires.

Every group of order pq (p != q primes) is Z_q x|_e Z_p with e^p = 1 (mod q).
For every such group with pq <= 40, and for every connection set of size 1 or 2
that generates the group, this script runs the constructive decision pipeline,
records which of the four criteria applies, and verifies the resulting cycle.

The census confirms, for this range, the order-pq theorem:
    every connected Cayley graph of a group of order pq is hamiltonian.
"""

from __future__ import annotations

from collections import Counter
from itertools import chain, combinations
from math import gcd
from typing import Dict, List, Optional, Sequence, Set, Tuple

Elt = Tuple[int, int]


class PQGroup:
    """Z_q x|_e Z_p :  (u,j)*(v,l) = (u + v e^j mod q, j + l mod p)."""

    identity: Elt = (0, 0)

    def __init__(self, q: int, p: int, e: int) -> None:
        self.q, self.p, self.e = q, p, e % q

    @property
    def order(self) -> int:
        return self.p * self.q

    def mul(self, g: Elt, h: Elt) -> Elt:
        return ((g[0] + h[0] * pow(self.e, g[1], self.q)) % self.q,
                (g[1] + h[1]) % self.p)

    def inv(self, g: Elt) -> Elt:
        ei = pow(self.e, (-g[1]) % self.p, self.q)
        return ((-g[0] * ei) % self.q, (-g[1]) % self.p)

    def power(self, g: Elt, n: int) -> Elt:
        acc = self.identity
        for _ in range(n):
            acc = self.mul(acc, g)
        return acc

    def order_of(self, g: Elt) -> int:
        n, acc = 1, g
        while acc != self.identity:
            acc = self.mul(acc, g)
            n += 1
        return n

    def in_normal(self, g: Elt) -> bool:
        return g[1] == 0

    def elements(self) -> List[Elt]:
        return [(u, j) for j in range(self.p) for u in range(self.q)]

    def generated(self, S: Sequence[Elt]) -> Set[Elt]:
        seen, stack = {self.identity}, [self.identity]
        while stack:
            g = stack.pop()
            for x in S:
                for h in (self.mul(g, x), self.mul(g, self.inv(x))):
                    if h not in seen:
                        seen.add(h)
                        stack.append(h)
        return seen


def direction_sequence(m: int, k: int, e: int) -> Optional[List[int]]:
    if e % m == 1 % m:
        if k % 2 == 0:
            return [1] * (k // 2) + [-1] * (k // 2)
        if m % 2 == 1 and m <= k:
            plus = (k + m) // 2
            return [1] * plus + [-1] * (k - plus)
        return None
    if gcd((e - 1) % m, m) == 1:
        return [1] * k
    return None


def torus_cycle(G: PQGroup, a: Elt, b: Elt, m: int, k: int,
                d: Sequence[int]) -> List[Elt]:
    cyc: List[Elt] = []
    g = G.identity
    for j in range(k):
        step = a if d[j] == 1 else G.inv(a)
        for i in range(m):
            cyc.append(g)
            if i < m - 1:
                g = G.mul(g, step)
        g = G.mul(g, b)
    return cyc


def lift(G: PQGroup, word: Sequence[Elt]) -> Optional[List[Elt]]:
    k = len(word)
    P = [G.identity]
    for s in word:
        P.append(G.mul(P[-1], s))
    z = P[k]
    m = G.order_of(z)
    if m * k != G.order:
        return None
    powers = [G.power(z, t) for t in range(m)]
    if len({frozenset(G.mul(x, P[i]) for x in powers) for i in range(k)}) != k:
        return None
    cyc = [G.mul(powers[t], P[i]) for t in range(m) for i in range(k)]
    return cyc if len(set(cyc)) == G.order else None


def pipeline(G: PQGroup, S: Sequence[Elt]) -> Tuple[str, Optional[List[Elt]]]:
    nz = [g for g in S if g != G.identity]
    for g in nz:
        if G.order_of(g) == G.order:
            return "cyclic generator", [G.power(g, i) for i in range(G.order)]
    a = next((g for g in nz if G.in_normal(g)), None)
    b = next((g for g in nz if not G.in_normal(g)), None)
    if a is not None and b is not None:
        m, k = G.order_of(a), G.order_of(b)
        if m * k == G.order:
            cands = [(a, b, m, k)]
            if G.e % G.q == 1 % G.q:
                cands.append((b, a, k, m))
            for (g1, g2, m1, k1) in cands:
                d = direction_sequence(m1, k1, G.e)
                if d is not None:
                    cyc = torus_cycle(G, g1, g2, m1, k1, d)
                    if len(set(cyc)) == G.order:
                        return "normal-subgroup pair", cyc
    for x in nz:
        for y in nz:
            if x == y:
                continue
            for yy, tag in ((y, "same coset"), (G.inv(y), "inverse cosets")):
                if yy != x and G.in_normal(G.mul(yy, G.inv(x))):
                    cyc = lift(G, [x] * (G.order_of(x) - 1) + [yy])
                    if cyc is not None:
                        return f"coset pair ({tag})", cyc
    for x in nz:
        k = G.order_of(x)
        for y in nz:
            if y == x:
                continue
            for alpha in range(k - 1):
                word = [x] * alpha + [y] + [G.inv(x)] * (k - 2 - alpha) + [y]
                cyc = lift(G, word)
                if cyc is not None:
                    return "partial transversal", cyc
    return "no criterion fired", None


def valid_cycle(G: PQGroup, S: Sequence[Elt], cyc: Sequence[Elt]) -> bool:
    moves = {s for s in S} | {G.inv(s) for s in S}
    n = len(cyc)
    return (len(set(cyc)) == G.order
            and all(G.mul(G.inv(cyc[i]), cyc[(i + 1) % n]) in moves
                    for i in range(n)))


def census(limit: int = 58) -> None:
    primes = [2, 3, 5, 7, 11, 13, 17, 19]
    tally: Counter[str] = Counter()
    tested = failures = 0
    print(f"{'|G|':>5}  {'group':<20} {'connected S':>12} {'hamiltonian':>12}")
    for p, q in combinations(primes, 2):
        if p * q > limit:
            continue
        exps = (sorted({pow(g, (q - 1) // p, q) for g in range(1, q)})
                if (q - 1) % p == 0 else [1])
        for e in exps:
            G = PQGroup(q, p, e)
            els = [g for g in G.elements() if g != G.identity]
            local = ok = 0
            for S in chain(combinations(els, 1), combinations(els, 2)):
                if len(G.generated(S)) != G.order:
                    continue
                local += 1
                name, cyc = pipeline(G, list(S))
                tally[name] += 1
                if cyc is not None and valid_cycle(G, S, cyc):
                    ok += 1
                else:
                    failures += 1
            tested += local
            label = (f"Z_{q} x Z_{p}" if G.e == 1 % G.q
                     else f"Z_{q} x|_{G.e} Z_{p}")
            print(f"{G.order:>5}  {label:<20} {local:>12} {ok:>12}")
    print(f"\ntotal connected connection sets: {tested}")
    print(f"failures: {failures}")
    print("criterion that fired:")
    for name, count in tally.most_common():
        print(f"   {name:<28} {count:>6}")


if __name__ == "__main__":
    census()

"""
Gray codes from hamiltonian cycles in Cayley graphs.

A hamiltonian cycle in the Cayley graph of G with connection set S is exactly a
cyclic Gray code for G: an ordering g_0, g_1, ..., g_{n-1} of ALL elements of G
in which consecutive entries differ by a single generator,

        g_i^{-1} g_{i+1}  in  S u S^{-1}   (indices modulo n).

This script produces such Gray codes explicitly:

  * for the cyclic group Z_n with S = {1}          (the trivial code);
  * for the abelian group Z_m x Z_k with S = {a,b} (the ploughing code, printed
    as a grid so the boustrophedon pattern is visible);
  * for the dihedral group of order 2n with S = {rotation, reflection};
  * for the metacyclic group Z_q x|_e Z_p.

Each code is verified: all elements appear exactly once and every consecutive
difference is a generator or the inverse of one.
"""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Sequence, Tuple

Elt = Tuple[int, int]


class Meta:
    """Z_q x|_e Z_p :  (u,j)*(v,l) = (u + v e^j mod q, j + l mod p)."""

    identity: Elt = (0, 0)

    def __init__(self, q: int, p: int, e: int = 1) -> None:
        assert pow(e, p, q) == 1 % q, "e must have order dividing p modulo q"
        self.q, self.p, self.e = q, p, e % q

    @property
    def order(self) -> int:
        return self.p * self.q

    def mul(self, g: Elt, h: Elt) -> Elt:
        return ((g[0] + h[0] * pow(self.e, g[1], self.q)) % self.q,
                (g[1] + h[1]) % self.p)

    def inv(self, g: Elt) -> Elt:
        ei = pow(self.e, (-g[1]) % self.p, self.q)
        return ((-g[0] * ei) % self.q, (-g[1]) % self.p)

    def order_of(self, g: Elt) -> int:
        n, acc = 1, g
        while acc != self.identity:
            acc = self.mul(acc, g)
            n += 1
        return n


def direction_sequence(m: int, k: int, e: int = 1) -> Optional[List[int]]:
    """Signs d with m | sum_j d_j e^j."""
    if e % m == 1 % m:
        if k % 2 == 0:
            return [1] * (k // 2) + [-1] * (k // 2)
        if m % 2 == 1 and m <= k:
            plus = (k + m) // 2
            return [1] * plus + [-1] * (k - plus)
        return None
    if gcd((e - 1) % m, m) == 1:
        return [1] * k
    return None


def gray_code(G: Meta, a: Elt, b: Elt) -> Optional[List[Elt]]:
    """Ring-by-ring Gray code for the pair (a, b), if the signs exist."""
    m, k = G.order_of(a), G.order_of(b)
    if m * k != G.order:
        return None
    for (g1, g2, m1, k1) in ((a, b, m, k), (b, a, k, m)):
        if G.e % G.q != 1 % G.q and (g1, g2) != (a, b):
            continue                      # roles are not exchangeable if twisted
        d = direction_sequence(m1, k1, G.e)
        if d is None:
            continue
        code: List[Elt] = []
        g = G.identity
        for j in range(k1):
            step = g1 if d[j] == 1 else G.inv(g1)
            for i in range(m1):
                code.append(g)
                if i < m1 - 1:
                    g = G.mul(g, step)
            g = G.mul(g, g2)
        if len(set(code)) == G.order:
            return code
    return None


def verify(G: Meta, S: Sequence[Elt], code: Sequence[Elt]) -> bool:
    moves = {s for s in S} | {G.inv(s) for s in S}
    n = len(code)
    return (len(set(code)) == G.order
            and all(G.mul(G.inv(code[i]), code[(i + 1) % n]) in moves
                    for i in range(n)))


def show(title: str, G: Meta, S: Sequence[Elt], code: Sequence[Elt],
         grid: bool = False) -> None:
    print(f"\n{title}")
    print(f"  |G| = {G.order}, S = {list(S)}, verified: {verify(G, S, code)}")
    if grid:
        pos = {g: t for t, g in enumerate(code)}
        for j in range(G.p):
            row = "  ".join(f"{pos[(u, j)]:>3}" for u in range(G.q))
            print(f"    coset {j}: {row}")
        print("    (entry t means: the t-th element of the Gray code)")
    else:
        print("   ", " ".join(f"({u},{j})" for u, j in code[:12]),
              "..." if len(code) > 12 else "")


def main() -> None:
    # 1. cyclic group Z_15 with a single generator
    G = Meta(15, 1, 1)
    a = (1, 0)
    code = [(i % 15, 0) for i in range(15)]
    show("Cyclic group of order 15, S = {a} with a a generator", G, [a], code)

    # 2. abelian Z_5 x Z_3 : the ploughing Gray code
    G = Meta(5, 3, 1)
    a, b = (1, 0), (0, 1)
    code = gray_code(G, a, b)
    assert code is not None
    show("Abelian group of order 15 = 5 * 3, S = {a, b}: the ploughing code",
         G, [a, b], code, grid=True)

    # 3. dihedral group of order 14
    G = Meta(7, 2, 6)
    a, b = (1, 0), (0, 1)
    code = gray_code(G, a, b)
    assert code is not None
    show("Dihedral group of order 14, S = {rotation, reflection}",
         G, [a, b], code, grid=True)

    # 4. metacyclic (Frobenius) group of order 21
    G = Meta(7, 3, 2)
    a, b = (1, 0), (0, 1)
    code = gray_code(G, a, b)
    assert code is not None
    show("Frobenius group of order 21 = 7 x| 3, S = {a, b}: the twisted code",
         G, [a, b], code, grid=True)
    print("\n  Note how the twist makes each coset be traversed in steps of "
          "e^j rather than 1.")


if __name__ == "__main__":
    main()

