"""
Algorithm 1 — Vertex-transitive backtracking search for a hamiltonian cycle
in a Cayley graph.

Because left translations are graph automorphisms, every hamiltonian cycle may
be assumed to start at the identity; this divides the search space by |G|.
The search is further pruned by a reachability test: if the not-yet-visited
vertices (together with the current vertex and the start) fall apart into more
than one component, the branch cannot be completed.
"""

from __future__ import annotations

from typing import Callable, Dict, Hashable, List, Optional, Sequence, Set

Elt = Hashable


def hamiltonian_cycle(
    elements: Sequence[Elt],
    mul: Callable[[Elt, Elt], Elt],
    inv: Callable[[Elt], Elt],
    identity: Elt,
    connection_set: Sequence[Elt],
) -> Optional[List[Elt]]:
    """Return a hamiltonian cycle of Cay(G, S) as a vertex list, or None."""
    moves: List[Elt] = []
    seen_moves: Set[Elt] = set()
    for s in connection_set:
        for t in (s, inv(s)):
            if t != identity and t not in seen_moves:
                seen_moves.add(t)
                moves.append(t)
    n = len(elements)
    if n < 3 or len(moves) < 2:
        return None

    adj: Dict[Elt, List[Elt]] = {g: [mul(g, m) for m in moves] for g in elements}
    path: List[Elt] = [identity]
    visited: Set[Elt] = {identity}

    def reachable_enough(current: Elt) -> bool:
        """Prune: the unvisited part must still be reachable from `current`."""
        stack, seen = [current], {current}
        while stack:
            g = stack.pop()
            for h in adj[g]:
                if h not in seen and (h not in visited or h == identity):
                    seen.add(h)
                    stack.append(h)
        return len(seen - {identity}) >= n - len(path)

    def extend(current: Elt) -> bool:
        if len(path) == n:
            return identity in adj[current]
        if not reachable_enough(current):
            return False
        for h in adj[current]:
            if h not in visited:
                visited.add(h)
                path.append(h)
                if extend(h):
                    return True
                path.pop()
                visited.remove(h)
        return False

    return list(path) if extend(identity) else None


if __name__ == "__main__":
    # Frobenius group of order 21 = Z_7 x|_2 Z_3, transversal connection set
    Q, P, E = 7, 3, 2
    els = [(u, j) for j in range(P) for u in range(Q)]
    m = lambda g, h: ((g[0] + h[0] * pow(E, g[1], Q)) % Q, (g[1] + h[1]) % P)
    iv = lambda g: ((-g[0] * pow(E, (-g[1]) % P, Q)) % Q, (-g[1]) % P)
    cyc = hamiltonian_cycle(els, m, iv, (0, 0), [(0, 1), (1, 2)])
    print("cycle length:", None if cyc is None else len(cyc))
    print("all distinct:", cyc is not None and len(set(cyc)) == len(els))

"""
Algorithm 4 — The order-pq decision pipeline.

Input: a group G of order p*q (necessarily Z_q x|_e Z_p) and a connection set S
generating G.  Output: the name of the criterion that applies together with an
explicit hamiltonian cycle.  This is the constructive content of the order-pq
theorem: every connected Cayley graph of a group of order pq is hamiltonian.

Branches, in the order tried:
  1. an element of order pq                 -> the power cycle 1, s, s^2, ...
  2. S meets the normal subgroup N          -> (twisted) direction sequence
  3. two elements in a common coset of N    -> word x,...,x,y  (factor group lemma)
     or in mutually inverse cosets          -> replace y by y^-1
  4. partial transversal                    -> word x,...,x, y, x^-1,...,x^-1, y

Each branch produces a cycle in O(|G|) group operations.
"""

from __future__ import annotations

from typing import List, Optional, Sequence, Tuple

Elt = Tuple[int, int]


class PQGroup:
    """Z_q x|_e Z_p :  (u,j)*(v,l) = (u + v e^j mod q, j + l mod p)."""

    def __init__(self, q: int, p: int, e: int) -> None:
        assert pow(e, p, q) == 1 % q
        self.q, self.p, self.e = q, p, e % q

    @property
    def order(self) -> int:
        return self.p * self.q

    identity: Elt = (0, 0)

    def mul(self, g: Elt, h: Elt) -> Elt:
        return ((g[0] + h[0] * pow(self.e, g[1], self.q)) % self.q,
                (g[1] + h[1]) % self.p)

    def inv(self, g: Elt) -> Elt:
        ei = pow(self.e, (-g[1]) % self.p, self.q)
        return ((-g[0] * ei) % self.q, (-g[1]) % self.p)

    def power(self, g: Elt, n: int) -> Elt:
        if n < 0:
            return self.power(self.inv(g), -n)
        acc = self.identity
        for _ in range(n):
            acc = self.mul(acc, g)
        return acc

    def order_of(self, g: Elt) -> int:
        n, acc = 1, g
        while acc != self.identity:
            acc = self.mul(acc, g)
            n += 1
        return n

    def in_normal(self, g: Elt) -> bool:
        return g[1] == 0


def direction_sequence(m: int, k: int, e: int = 1) -> Optional[List[int]]:
    """Signs d in {+1,-1}^k with m | sum_j d_j e^j (see Algorithm 3)."""
    from math import gcd

    if e % m == 1 % m:
        if k % 2 == 0:
            return [1] * (k // 2) + [-1] * (k // 2)
        if m % 2 == 1 and m <= k:
            plus = (k + m) // 2
            return [1] * plus + [-1] * (k - plus)
        return None
    if gcd((e - 1) % m, m) == 1:
        return [1] * k
    return None


def torus_cycle(
    G: PQGroup, a: Elt, b: Elt, m: int, k: int, d: Sequence[int]
) -> List[Elt]:
    """Traverse ring j with m-1 steps of a^{d_j}, then one step of b."""
    cyc: List[Elt] = []
    g = G.identity
    for j in range(k):
        step = a if d[j] == 1 else G.inv(a)
        for i in range(m):
            cyc.append(g)
            if i < m - 1:
                g = G.mul(g, step)
        g = G.mul(g, b)
    return cyc


def _lift(G: PQGroup, word: Sequence[Elt]) -> Optional[List[Elt]]:
    k = len(word)
    P = [G.identity]
    for s in word:
        P.append(G.mul(P[-1], s))
    z = P[k]
    m = G.order_of(z)
    if m * k != G.order:
        return None
    powers = [G.power(z, t) for t in range(m)]
    cosets = {frozenset(G.mul(x, P[i]) for x in powers) for i in range(k)}
    if len(cosets) != k:
        return None
    cycle = [G.mul(powers[t], P[i]) for t in range(m) for i in range(k)]
    return cycle if len(set(cycle)) == G.order else None


def hamiltonian_pipeline(
    G: PQGroup, S: Sequence[Elt]
) -> Tuple[str, Optional[List[Elt]]]:
    """Return (criterion name, explicit hamiltonian cycle)."""
    nz = [g for g in S if g != G.identity]

    # 1. a generator
    for g in nz:
        if G.order_of(g) == G.order:
            return "cyclic generator", [G.power(g, i) for i in range(G.order)]

    # 2. S meets the normal subgroup N: ring-by-ring traversal of the torus
    a = next((g for g in nz if G.in_normal(g)), None)
    b = next((g for g in nz if not G.in_normal(g)), None)
    if a is not None and b is not None:
        m, k = G.order_of(a), G.order_of(b)
        if m * k == G.order:
            # in the abelian case the two generators may be exchanged, which is
            # what makes the parity-free choice of signs always possible
            candidates = [(a, b, m, k)]
            if G.e % G.q == 1 % G.q:
                candidates.append((b, a, k, m))
            for (g1, g2, m1, k1) in candidates:
                d = direction_sequence(m1, k1, G.e)
                if d is None:
                    continue
                cyc = torus_cycle(G, g1, g2, m1, k1, d)
                if len(set(cyc)) == G.order:
                    return "normal-subgroup pair (twisted direction sequence)", cyc

    # 3. two elements in a common or in mutually inverse cosets of N
    for i in range(len(nz)):
        for j in range(len(nz)):
            if i == j:
                continue
            x, y = nz[i], nz[j]
            for yy, tag in ((y, "same coset"), (G.inv(y), "inverse cosets")):
                if G.in_normal(G.mul(yy, G.inv(x))) and yy != x:
                    k = G.order_of(x)
                    cyc = _lift(G, [x] * (k - 1) + [yy])
                    if cyc is not None:
                        return f"coset pair ({tag})", cyc

    # 4. partial transversal: the coset-pair word
    for x in nz:
        k = G.order_of(x)
        for y in nz:
            if y == x:
                continue
            for alpha in range(k - 1):
                beta = k - 2 - alpha
                word = [x] * alpha + [y] + [G.inv(x)] * beta + [y]
                cyc = _lift(G, word)
                if cyc is not None:
                    return "partial transversal (coset-pair word)", cyc
    return "no criterion fired", None


if __name__ == "__main__":
    tests = [
        (7, 3, 2, [(0, 1), (1, 2)]),   # transversal in the Frobenius group of order 21
        (7, 3, 1, [(1, 0), (0, 1)]),   # abelian normal pair, order 21
        (7, 2, 6, [(1, 0), (0, 1)]),   # dihedral of order 14
        (11, 5, 3, [(0, 1), (1, 3)]),  # transversal in order 55
    ]
    for q, p, e, S in tests:
        G = PQGroup(q, p, e)
        name, cyc = hamiltonian_pipeline(G, S)
        ok = cyc is not None and len(set(cyc)) == G.order
        print(f"|G|={G.order:<3} e={e}  S={S}  ->  {name:<45} cycle: {ok}")
